parameters.new_string:
	var actualProcessedCount int32 // To count results read from the channel

	var resultWg sync.WaitGroup
	resultWg.Add(1)
	go func() {
		defer resultWg.Done()
		for range results {
			atomic.AddInt32(&actualProcessedCount, 1)
		}
	}()

	// Send jobs
	go func() {
		for i := 0; i < numJobs; i++ {
			jobs <- Job{ID: i}
		}
		close(jobs)
	}()

	// Wait for all workers to finish processing jobs
	wg.Wait()
	// Close the results channel AFTER all workers have finished sending results
	close(results)

	// Wait for the result consumer goroutine to finish
	resultWg.Wait()

	return int(actualProcessedCount), nil
}

